var HELPER = "(function(){\n/* Mesin bacaan bersama Hijaiyah Playland.\n   Satu \"unit\" = beberapa huruf + tanda bacanya, mis. \u0628\u064e / \u0628\u0650 / \u0628\u064b / \u0628\u064e\u062a\u0652 / \u0631\u064e\u0628\u064e\u0651 / \u0628\u064e\u062c\u064e\u0633\u064e.\n   Semua wahana mengambil soal dari sini sesuai HP.tingkat. */\nvar H = window.HP || (window.HP = {});\nvar F=\"\u064e\", K=\"\u0650\", D=\"\u064f\", FT=\"\u064b\", KT=\"\u064d\", DT=\"\u064c\", SK=\"\u0652\", SY=\"\u0651\";\nvar HUR = \"\u0627\u0628\u062a\u062b\u062c\u062d\u062e\u062f\u0630\u0631\u0632\u0633\u0634\u0635\u0636\u0637\u0638\u0639\u063a\u0641\u0642\u0643\u0644\u0645\u0646\u0648\u0647\u064a\".split(\"\");\nvar SAMBUNG = HUR.filter(function(h){ return \"\u0627\u062f\u0630\u0631\u0632\u0648\".indexOf(h) \u003c 0; });   /* huruf yang menyambung ke kiri */\nvar MIRIP = [\"\u0628\u062a\u062b\",\"\u062c\u062d\u062e\",\"\u062f\u0630\",\"\u0631\u0632\",\"\u0633\u0634\",\"\u0635\u0636\",\"\u0637\u0638\",\"\u0639\u063a\",\"\u0641\u0642\"];\nvar V = [\"a\",\"i\",\"u\"];\nvar NAMA = {}; [\"Alif\",\"Ba\",\"Ta\",\"Tsa\",\"Jim\",\"\\u1E24a\",\"Kho\",\"Dal\",\"Dzal\",\"Ro\",\"Zay\",\"Sin\",\"Syin\",\"Shod\",\"Dhod\",\"Tho\",\"Zho\",\"'Ain\",\"Ghoin\",\"Fa\",\"Qof\",\"Kaf\",\"Lam\",\"Mim\",\"Nun\",\"Wau\",\"Ha\",\"Ya\"].forEach(function(n, i){ NAMA[HUR[i]] = n; });\nvar B = {\"\u0627\":[\"a\",\"i\",\"u\"],\"\u0628\":\"b\",\"\u062a\":\"t\",\"\u062b\":\"ts\",\"\u062c\":\"j\",\"\u062d\":[\"\u1e25a\",\"\u1e25i\",\"\u1e25u\",\"\u1e25\"],\n  \"\u062e\":[\"kho\",\"khi\",\"khu\",\"kh\"],\"\u062f\":\"d\",\"\u0630\":\"dz\",\"\u0631\":[\"ro\",\"ri\",\"ru\",\"r\"],\"\u0632\":\"z\",\"\u0633\":\"s\",\"\u0634\":\"sy\",\n  \"\u0635\":[\"sho\",\"shi\",\"shu\",\"sh\"],\"\u0636\":[\"dho\",\"dhi\",\"dhu\",\"dh\"],\"\u0637\":[\"tho\",\"thi\",\"thu\",\"th\"],\"\u0638\":[\"zho\",\"zhi\",\"zhu\",\"zh\"],\n  \"\u0639\":[\"'a\",\"'i\",\"'u\",\"'\"],\"\u063a\":[\"gho\",\"ghi\",\"ghu\",\"gh\"],\"\u0641\":\"f\",\"\u0642\":[\"qo\",\"qi\",\"qu\",\"q\"],\"\u0643\":\"k\",\"\u0644\":\"l\",\n  \"\u0645\":\"m\",\"\u0646\":\"n\",\"\u0648\":\"w\",\"\u0647\":\"h\",\"\u064a\":\"y\",\"\u0621\":[\"a\",\"i\",\"u\",\"\"]};\nfunction suku(l, i){ var b = B[l]; return typeof b === \"string\" ? b + V[i] : b[i]; }\nfunction akar(l){ var b = B[l]; return typeof b === \"string\" ? b : b[3]; }\nvar VOK = {}; VOK[F]=0; VOK[K]=1; VOK[D]=2;\nvar TAN = {}; TAN[FT]=0; TAN[KT]=1; TAN[DT]=2;\nfunction bunyiUnit(s, m){\n  var t = \"\";\n  for (var i=0;i\u003cs.length;i++){\n    var l = s[i], k = m[i];\n    if (k === \"\") t += NAMA[l] || l;\n    else if (k in VOK) t += suku(l, VOK[k]);\n    else if (k in TAN) t += suku(l, TAN[k]) + \"n\";\n    else if (k === SK) t += akar(l);\n    else if (k.charAt(0) === SY) t += akar(l) + suku(l, VOK[k.charAt(1)]);\n  }\n  t = t.replace(/''/g, \"'\");\n  var a = t.charAt(0) === \"'\" ? 1 : 0;\n  return t.slice(0,a) + t.charAt(a).toUpperCase() + t.slice(a+1);\n}\nfunction teks(s, m){ var t = \"\"; for (var i=0;i\u003cs.length;i++) t += s[i] + m[i]; return t; }\nfunction unit(s, m){ return {s:s, m:m, t:teks(s,m), b:bunyiUnit(s,m)}; }\nfunction pilih(a){ return a[Math.random()*a.length|0]; }\nfunction sibling(l){ for (var i=0;i\u003cMIRIP.length;i++) if (MIRIP[i].indexOf(l) \u003e= 0){ var g = MIRIP[i].split(\"\").filter(function(x){ return x !== l; }); return pilih(g); } return null; }\n\n/* ---------- definisi tingkat ---------- */\nvar T = {\n  huruf:  {marks:[\"\"], nama:true},\n  a:      {marks:[F]},\n  ai:     {marks:[F,K]},\n  aiu:    {marks:[F,K,D]},\n  tanwin: {marks:[FT,KT,DT], tanpa:\"\u0627\"}\n  \n};\nvar C = T[H.tingkat] || T.huruf;\nH.harakat = !C.nama;\nH.multi = !!C.multi;\nH.marks = C.nama ? null : (C.marks || null);\nH.bunyi = function(l, i){ return B[l] ? suku(l, i) : \"\"; };\nH.bunyiCap = function(l, i){ return bunyiUnit([l],[[F,K,D][i]]); };\nH.teksHuruf = function(l, i){ return unit([l],[C.marks ? C.marks[i % C.marks.length] : F]); };\n\n/* satu unit acak (opsional: huruf dasar tertentu, untuk tingkat satu huruf) */\nH.acak = function(dasar){\n  if (C.buat) return C.buat();\n  var pool = HUR.filter(function(h){ return h !== C.tanpa; });\n  var l = dasar \u0026\u0026 pool.indexOf(dasar) \u003e= 0 ? dasar : pilih(pool);\n  return unit([l],[pilih(C.marks)]);\n};\n/* n unit yang mirip tetapi berbeda: tanda lain atau huruf kembar-rupa */\nH.mirip = function(u, n){\n  var hasil = [], kunci = {}; kunci[u.t] = 1;\n  var posisi = C.posisi || [C.marks];\n  function tambah(v){ if (v \u0026\u0026 !kunci[v.t]){ kunci[v.t] = 1; hasil.push(v); } }\n  for (var coba=0; coba\u003c60 \u0026\u0026 hasil.length\u003cn; coba++){\n    var s = u.s.slice(), m = u.m.slice(), i = Math.random()*s.length|0, r = Math.random();\n    if (r \u003c 0.5 \u0026\u0026 posisi[i] \u0026\u0026 posisi[i].length \u003e 1) m[i] = pilih(posisi[i].filter(function(x){ return x !== m[i]; }));\n    else { var sb = sibling(s[i]); if (sb \u0026\u0026 !(C.tanpa \u0026\u0026 sb === C.tanpa)) s[i] = sb; else if (coba \u003e 20) s[i] = pilih(HUR.filter(function(h){ return h !== s[i] \u0026\u0026 h !== C.tanpa \u0026\u0026 h !== \"\u0627\"; })); else continue; }\n    if (C.multi \u0026\u0026 s[0] !== \"\u0627\" \u0026\u0026 m[1] === SK \u0026\u0026 \"\u0627\u0648\u064a\".indexOf(s[1]) \u003e= 0) continue;\n    tambah(unit(s, m));\n  }\n  while (hasil.length \u003c n) tambah(H.acak());\n  return hasil;\n};\n/* daftar unit untuk satu permainan */\nH.daftar = function(maks){\n  if (C.buat){ var d = [], k = {}; for (var i=0; i\u003c400 \u0026\u0026 d.length\u003c(maks||40); i++){ var u = C.buat(); if (!k[u.t]){ k[u.t] = 1; d.push(u); } } return d; }\n  var out = [];\n  HUR.forEach(function(h){ if (h === C.tanpa) return; C.marks.forEach(function(mk){ out.push(unit([h],[mk])); }); });\n  return out;\n};\nH.ucapID = function(t){\n  try{ var S = window.speechSynthesis; if (!S) return; S.cancel();\n    var u = new SpeechSynthesisUtterance(String(t).replace(/'/g,\"\").replace(/\u1e25/g,\"h\"));\n    u.lang = \"id-ID\"; u.rate = 0.85; S.speak(u); }catch(e){}\n};\nH.lapor = function(o){ o = o || {}; try{ parent.postMessage({hp:\"hasil\", game:H.game, data:o}, \"*\"); }catch(e){} };\nif (H.multi) document.documentElement.className += \" hp-multi\";\n})();\n";

